test('initDb should create database and apply migrations', async () => {
  await initDb();
  const todos = await getTodos();
  expect(Array.isArray(todos)).toBe(true);
  expect(todos.length).toBe(0);
});

test('initDb should be idempotent when called multiple times', async () => {
  await initDb();
  await initDb();
  const todos = await getTodos();
  expect(Array.isArray(todos)).toBe(true);
});

test('initDb should apply both migrations', async () => {
  await initDb();
  await addTodo('Test migration');
  const todos = await getTodos();
  expect(todos[0]).toHaveProperty('id');
  expect(todos[0]).toHaveProperty('text');
  expect(todos[0]).toHaveProperty('completed');
  expect(todos[0]).toHaveProperty('deleted');
});

test('addTodo should insert a new todo', async () => {
  await initDb();
  await addTodo('Buy groceries');
  const todos = await getTodos();
  expect(todos.length).toBe(1);
  expect(todos[0].text).toBe('Buy groceries');
  expect(todos[0].completed).toBe(0);
  expect(todos[0].deleted).toBe(0);
});

test('addTodo should handle special characters and prevent SQL injection', async () => {
  await initDb();
  await addTodo("Test'; DROP TABLE todos; --");
  const todos = await getTodos();
  expect(todos.length).toBe(1);
  expect(todos[0].text).toBe("Test'; DROP TABLE todos; --");
});

test('addTodo should handle empty string', async () => {
  await initDb();
  await addTodo('');
  const todos = await getTodos();
  expect(todos.length).toBe(1);
  expect(todos[0].text).toBe('');
});

test('getTodos should return empty array when no todos exist', async () => {
  await initDb();
  const todos = await getTodos();
  expect(todos).toEqual([]);
});

test('getTodos should return todos in descending order by id', async () => {
  await initDb();
  await addTodo('First');
  await addTodo('Second');
  await addTodo('Third');
  const todos = await getTodos();
  expect(todos.length).toBe(3);
  expect(todos[0].text).toBe('Third');
  expect(todos[1].text).toBe('Second');
  expect(todos[2].text).toBe('First');
});

test('getTodos should exclude deleted todos', async () => {
  await initDb();
  await addTodo('Keep this');
  await addTodo('Delete this');
  const todos = await getTodos();
  const todoToDelete = todos.find(t => t.text === 'Delete this');
  await deleteTodo(todoToDelete.id);
  const remaining = await getTodos();
  expect(remaining.length).toBe(1);
  expect(remaining[0].text).toBe('Keep this');
});

test('toggleTodo should mark uncompleted todo as completed', async () => {
  await initDb();
  await addTodo('Task to complete');
  const todos = await getTodos();
  const todo = todos[0];
  expect(todo.completed).toBe(0);
  await toggleTodo(todo.id);
  const updated = await getTodos();
  expect(updated[0].completed).toBe(1);
});

test('toggleTodo should mark completed todo as uncompleted', async () => {
  await initDb();
  await addTodo('Task to toggle');
  const todos = await getTodos();
  const todo = todos[0];
  await toggleTodo(todo.id);
  await toggleTodo(todo.id);
  const updated = await getTodos();
  expect(updated[0].completed).toBe(0);
});

test('toggleTodo should handle non-existent id gracefully', async () => {
  await initDb();
  await expect(toggleTodo(99999)).resolves.not.toThrow();
});

test('updateTodo should change todo text', async () => {
  await initDb();
  await addTodo('Original text');
  const todos = await getTodos();
  const todo = todos[0];
  await updateTodo(todo.id, 'Updated text');
  const updated = await getTodos();
  expect(updated[0].text).toBe('Updated text');
  expect(updated[0].id).toBe(todo.id);
});

test('updateTodo should handle special characters', async () => {
  await initDb();
  await addTodo('Test');
  const todos = await getTodos();
  await updateTodo(todos[0].id, "O'Reilly & Sons <script>alert('xss')</script>");
  const updated = await getTodos();
  expect(updated[0].text).toBe("O'Reilly & Sons <script>alert('xss')</script>");
});

test('updateTodo should throw error for non-existent id', async () => {
  await initDb();
  await expect(updateTodo(99999, 'New text')).rejects.toThrow();
});

test('deleteTodo should mark todo as deleted without removing from database', async () => {
  await initDb();
  await addTodo('To be deleted');
  const todos = await getTodos();
  const todo = todos[0];
  await deleteTodo(todo.id);
  const remaining = await getTodos();
  expect(remaining.length).toBe(0);
  const allTodos = await db.query('SELECT * FROM todos WHERE id = ?', [todo.id]);
  expect(allTodos.length).toBe(1);
  expect(allTodos[0].deleted).toBe(1);
});

test('deleteTodo should throw error for non-existent id', async () => {
  await initDb();
  await expect(deleteTodo(99999)).rejects.toThrow();
});

test('deleteTodo should not affect other todos', async () => {
  await initDb();
  await addTodo('Keep this');
  await addTodo('Delete this');
  const todos = await getTodos();
  const toDelete = todos.find(t => t.text === 'Delete this');
  await deleteTodo(toDelete.id);
  const remaining = await getTodos();
  expect(remaining.length).toBe(1);
  expect(remaining[0].text).toBe('Keep this');
});

test('initDb should not reinitialize if db already exists', async () => {
  await initDb();
  await addTodo('First todo');
  await initDb();
  const todos = await getTodos();
  expect(todos.length).toBe(1);
  expect(todos[0].text).toBe('First todo');
});

test('addTodo should handle database errors without throwing', async () => {
  await initDb();
  const consoleSpy = jest.spyOn(console, 'error').mockImplementation();
  db.execute = jest.fn().mockRejectedValue(new Error('Database error'));
  await addTodo('This will fail');
  expect(consoleSpy).toHaveBeenCalledWith('Failed to add todo:', expect.any(Error));
  consoleSpy.mockRestore();
});

test('getTodos should return empty array when query returns null', async () => {
  await initDb();
  const originalQuery = db.query;
  db.query = jest.fn().mockResolvedValue(null);
  const todos = await getTodos();
  expect(todos).toEqual([]);
  db.query = originalQuery;
});

test('migration v2 should add deleted column to existing todos', async () => {
  await initDb();
  await addTodo('Test todo');
  const todos = await getTodos();
  expect(todos[0]).toHaveProperty('deleted');
  expect(todos[0].deleted).toBe(0);
});

